CREATE FUNCTION public.update_reminder(p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE r public.reminders;BEGIN SELECT * INTO r FROM public.reminders WHERE id=(p->>'id')::uuid FOR UPDATE;IF NOT FOUND OR NOT (public.staff_can('Create bills',r.branch_id) OR public.staff_can('Collect repayments',r.branch_id)) THEN RAISE EXCEPTION 'Permission required';END IF;IF r.done_at IS NOT NULL THEN RAISE EXCEPTION 'Completed reminders cannot be edited';END IF;UPDATE public.reminders SET title=trim(p->>'title'),note=coalesce(p->>'note',''),remind_date=(p->>'remind_date')::date WHERE id=r.id;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),r.branch_id,'Reminders','Updated','Edited reminder "'||trim(p->>'title')||'" for '||(p->>'remind_date'),r.id::text);END$$;
CREATE FUNCTION public.delete_reminder(rid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE r public.reminders;BEGIN SELECT * INTO r FROM public.reminders WHERE id=rid FOR UPDATE;IF NOT FOUND OR NOT (public.staff_can('Create bills',r.branch_id) OR public.staff_can('Collect repayments',r.branch_id)) THEN RAISE EXCEPTION 'Permission required';END IF;DELETE FROM public.reminders WHERE id=rid;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),r.branch_id,'Reminders','Deleted','Deleted reminder "'||r.title||'"',rid::text);END$$;
REVOKE EXECUTE ON FUNCTION public.update_reminder(jsonb),public.delete_reminder(uuid) FROM anon,public;
GRANT EXECUTE ON FUNCTION public.update_reminder(jsonb),public.delete_reminder(uuid) TO authenticated;